  "표3_신학적의미": [
    {"교리": "은혜와 평강의 신학", "설명": "은혜(카리스)가 먼저이고 평강(에이레네)은 그 결과이다. 하나님의 값없는 은혜를 받을 때 비로소 진정한 평강이 임한다. 이 순서는 구원론적으로 중요하다", "관련구절": "롬 5:1, 엡 2:8, 빌 4:7, 요 14:27"},
    {"교리": "성부와 성자의 공동 출처", "설명": "은혜와 평강이 하나님 우리 아버지와 주 예수 그리스도 두 분에게서 함께 온다. 이는 성부와 성자의 동등한 신성과 은혜의 공동 출처를 선언한다", "관련구절": "고후 13:13, 요 1:14, 갈 1:3, 딛 1:4"}
  ],
  "표4_예표론": [
    {"구분": "제사장의 축복과 복음의 인사", "내용": "구약에서 아론의 제사장 축복(민 6:24-26)은 하나님의 은혜와 평강을 비는 것이었다. 이것이 바울의 인사에서 그리스도를 통해 성취된다", "그리스도연결": "대제사장이신 그리스도께서 모든 성도에게 은혜와 평강을 베푸신다(히 7:25). 우리의 대제사장이 된 예수님이 가장 완전한 축복을 주신다"},
    {"구분": "샬롬의 성취", "내용": "구약의 샬롬(평화, 온전함, 완전한 번성)이 그리스도 안에서 성취된다. 이사야가 예언한 평화의 왕(사 9:6)이 바로 주 예수 그리스도이시다", "그리스도연결": "그리스도는 우리의 화평이 되셨다(엡 2:14). 그분을 통해 하나님과의 화평이 회복되고 진정한 샬롬이 임한다"}
  ],
  "표5_매튜헨리": [
    {"영어원문": "Grace and peace from God our Father and the Lord Jesus Christ — this is the very summary of the gospel, grace is its beginning, peace is its fruit; the one is the cause, the other is the effect.", "한국어번역": "하나님 우리 아버지와 주 예수 그리스도로부터 오는 은혜와 평강 — 이것이 복음의 요약이다. 은혜는 시작이고 평강은 열매이며 하나는 원인이고 다른 하나는 결과이다.", "핵심통찰": "복음은 은혜로 시작하여 평강으로 열매를 맺는다"},
    {"영어원문": "The apostle mentions both Father and Son as the joint source of these blessings, which strongly implies the divinity of the Son and his equality with the Father.", "한국어번역": "사도는 성부와 성자 모두를 이 축복의 공동 출처로 언급한다. 이는 성자의 신성과 성부와의 동등성을 강력하게 암시한다.", "핵심통찰": "바울의 간단한 인사 속에 삼위일체 신학이 담겨 있다"}
  ],
  "표6_설교자료": [
    {"대지": "제목", "내용": "은혜와 평강: 핍박 중에 누리는 하늘의 선물", "예화_적용": "세상이 줄 수 없는 것을 하나님이 주신다. 핍박받는 성도에게 하나님이 약속하시는 은혜와 평강이 있다"},
    {"대지": "서론", "내용": "바울은 핍박받는 교회에 편지를 쓰면서 은혜와 평강을 기원한다. 이것은 단순한 인사가 아닌 신학적 선언이다. 고통 중에 있는 성도에게 가장 필요한 것이 무엇인지 바울은 알았다", "예화_적용": "전쟁터에 있는 병사에게 평화 소식만큼 귀한 것은 없다. 영적 전쟁 중에 있는 성도에게 하나님의 평강 선언은 가장 큰 위로이다"},
    {"대지": "1대지: 은혜 — 모든 것의 시작 (원천)", "내용": "은혜는 하나님이 값없이 베푸시는 호의이다. 우리가 잘해서가 아니라 하나님이 좋으셔서 주시는 것이다. 핍박을 받는 것도 은혜, 그 안에서 버티는 것도 은혜이다", "예화_적용": "가뭄에도 마르지 않는 샘처럼 하나님의 은혜는 어떤 환경에도 마르지 않는다. 성도의 삶은 이 샘에서 매일 마신다"},
    {"대지": "2대지: 평강 — 은혜의 열매 (결과)", "내용": "평강은 하나님과의 관계 회복에서 오는 온전한 샬롬이다. 박해가 있어도 혼란이 있어도 하나님이 주시는 평강은 세상이 빼앗을 수 없다(요 14:27)", "예화_적용": "폭풍 속에서도 고요한 강 바닥처럼 하나님의 평강은 표면의 폭풍과 관계없이 깊은 곳에 있다"},
    {"대지": "3대지: 성부와 성자에게서 함께 오는 축복 (근거)", "내용": "은혜와 평강이 하나님 우리 아버지와 주 예수 그리스도에게서 함께 온다. 이 축복의 이중 출처는 우리의 복이 얼마나 든든한지를 보여준다", "예화_적용": "두 왕이 함께 서명한 조약처럼 성부와 성자가 함께 약속하신 은혜와 평강은 절대 취소되지 않는다"},
    {"대지": "결론", "내용": "핍박과 혼란 속에서 성도에게 필요한 것은 바로 이 은혜와 평강이다. 하나님 아버지와 주 예수 그리스도로부터 오는 이 축복은 세상이 빼앗을 수 없다. 오늘도 이 은혜와 평강 안에서 살아가자", "예화_적용": "아무리 힘든 날도 하나님의 은혜와 평강으로 하루를 시작하는 사람은 그 날을 이길 수 있다"}
  ],
  "표7_찬송가": [
    {"새찬송가": "305", "통일찬송가": "412", "제목": "나 같은 죄인 살리신", "선정이유": "값없는 은혜로 죄인을 살리신 하나님의 은혜를 노래한다"},
    {"새찬송가": "413", "통일찬송가": "470", "제목": "내 영혼의 그윽히 깊은 데서", "선정이유": "세상이 줄 수 없는 하나님의 깊은 평강을 고백한다"},
    {"새찬송가": "382", "통일찬송가": "435", "제목": "너 근심 걱정 말아라", "선정이유": "핍박 속에서도 하나님의 은혜로 누리는 평안을 노래한다"},
    {"새찬송가": "428", "통일찬송가": "491", "제목": "예수 따라가며", "선정이유": "주 예수 그리스도를 따라 은혜와 평강을 누리는 삶을 담는다"}
  ],
  "표8_상담적용": [
    {"상황": "불안과 두려움으로 잠을 이루지 못하는 분", "성경원리": "하나님이 주시는 평강은 세상이 줄 수 없다(요 14:27). 이 평강은 모든 지각에 뛰어나다(빌 4:7). 하나님 아버지와 주 예수 그리스도로부터 오는 평강은 어떤 상황도 이긴다", "실제적용": "불안의 원인을 살피되 궁극적 평강의 출처가 하나님임을 가르치고 매일 아침 은혜와 평강을 구하는 기도 습관을 형성하도록 도우라"},
    {"상황": "구원의 확신이 없어 불안한 분", "성경원리": "은혜는 하나님이 값없이 주시는 것이다. 우리의 행위나 공로에 의존하지 않는다. 이 은혜의 확실성이 평강의 근거이다", "실제적용": "하나님의 은혜가 행위가 아닌 믿음으로 받는 것임을 성경을 통해 확인하고 구원의 객관적 근거(그리스도의 십자가)에 집중하도록 인도하라"}
  ],
  "표9_교차참조": [
    {"구절": "민 6:24-26", "연결점": "아론의 제사장 축복에서 은혜와 평강을 기원 — 바울 인사의 구약적 원형", "구분": "구약"},
    {"구절": "롬 5:1", "연결점": "믿음으로 의롭다 하심을 얻어 하나님과 화평을 누림 — 은혜에서 평강이 오는 논리적 전개", "구분": "신약"},
    {"구절": "엡 2:8", "연결점": "은혜로 구원을 받음이라 너희의 것이 아니요 하나님의 선물 — 은혜의 본질", "구분": "신약"},
    {"구절": "빌 4:7", "연결점": "모든 지각에 뛰어난 하나님의 평강 — 에이레네의 신학적 깊이", "구분": "신약"},
    {"구절": "요 14:27", "연결점": "내가 주는 평안은 세상이 주는 것과 같지 않다 — 하나님의 평강의 독특성", "구분": "신약"},
    {"구절": "사 9:6", "연결점": "평화의 왕이신 메시아 예언 — 그리스도를 통한 샬롬의 성취", "구분": "구약"},
    {"구절": "엡 2:14", "연결점": "그리스도는 우리의 화평 — 평강의 근거가 그리스도임을 선언", "구분": "신약"},
    {"구절": "갈 1:3", "연결점": "동일한 형식의 인사 — 바울 서신의 일관된 복음적 인사 형식", "구분": "신약"}
  ]
