    {"항목": "안식으로의 갚음", "내용": "핍박받는 성도들에게 안식을 약속하는 것은 종말론적 위로이다. 바울 자신도 이 안식에 참여할 것이라고 한다(우리와 함께). 이는 사역자와 성도가 함께 누릴 종말론적 안식이다", "목회적활용": "종말론적 안식은 현재의 고난을 견디게 하는 가장 강력한 동기이다. 목회자도 성도와 함께 이 안식을 소망하며 살아야 한다"}
