    {"구분": "광야의 안식과 하늘의 안식", "내용": "이스라엘에게 약속된 안식의 땅(가나안)이 구약적 안식의 예표였다. 성도에게 약속된 종말론적 안식은 그 완전한 성취이다", "그리스도연결": "그리스도께서 수고하고 무거운 짐 진 자에게 쉬게 하리라 약속하셨다(마 11:28). 이 안식은 그리스도 안에서 시작되고 완성된다"}
