    {"구분": "다니엘의 인자 강림과 재림", "내용": "다니엘이 본 인자가 구름을 타고 하늘 법정에 나타나는 환상(단 7:13-14)이 주 예수의 재림의 예표이다. 예수님이 스스로 인자로 자신을 부르신 것(마 24:30)이 이를 확인한다", "그리스도연결": "그리스도는 다니엘서의 인자이시다. 그분의 재림은 다니엘의 예언의 최종 성취이다"}
