    {"새찬송가": "180", "통일찬송가": "179", "제목": "저 요단강 건너편에", "선정이유": "재림 때 주 앞에 모이는 영광을 소망하며 노래한다"},
    {"새찬송가": "606", "통일찬송가": "606", "제목": "주 안에서 기뻐해", "선정이유": "재림의 소망으로 현재의 어려움을 이기는 기쁨을 담는다"},
    {"새찬송가": "174", "통일찬송가": "174", "제목": "주 강림하실 때", "선정이유": "주의 공식적이고 영광스러운 재림을 노래한다"}
