    {"구절": "계 13:1-8", "연결점": "바다에서 올라온 짐승 — 불법의 사람의 계시록적 병행", "구분": "신약"},
    {"구절": "겔 28:2", "연결점": "자신이 신이라 하는 두로 왕 — 불법의 사람이 하나님 위에 스스로 높이는 구약적 예표", "구분": "구약"}
