    {"상황": "권위에 대한 반항심이 강해 모든 권위를 대적하는 분", "성경원리": "대적(안티케이메노스)하는 것이 불법의 사람의 본성이다. 하나님이 세우신 권위를 대적하는 것은 결국 하나님을 대적하는 것이다", "실제적용": "권위에 대한 상처나 불신을 충분히 공감하되 하나님이 세우신 권위의 의미를 가르치라. 불의한 권위와 정당한 권위를 분별하도록 돕되 기본적 순종의 가치를 가르치라"}
