    {"구절": "행 2:42", "연결점": "사도의 가르침을 받아 서로 교제하고 — 사도적 가르침 보존의 중요성", "구분": "신약"},
    {"구절": "눅 22:19", "연결점": "이것을 행하여 나를 기념하라 — 기억이 신앙의 핵심 행위임", "구분": "신약"},
    {"구절": "시 78:5-7", "연결점": "우리 조상들에게 증거를 세우사 자손에게 전하게 하셨으니 — 대대로 기억하고 전하라", "구분": "구약"}
