    {"상황": "불법하고 부도덕한 세상에서 어떻게 살아야 할지 모르는 분", "성경원리": "불법의 비밀이 활동하는 세상에서 성도는 분별력 있게 살아야 한다. 하나님의 억제 안에서 성도는 보호받는다. 진리를 붙들고 성령의 인도를 따르는 것이 답이다", "실제적용": "세상의 불법에 압도되지 않도록 하나님의 보호와 성도의 분별력을 가르치라. 구체적인 영적 분별의 방법(기도, 말씀, 공동체)을 함께 살피라"}
