    {"상황": "악인이 형통하고 의인이 고난받는 현실에 분노하는 분", "성경원리": "불법한 자는 반드시 그리스도의 재림 때 멸망한다. 지금의 형통이 끝이 아니다. 하나님의 최종 심판이 모든 것을 바로잡는다", "실제적용": "분노의 감정을 인정하되 그리스도의 최종 심판과 승리를 가르치라. 지금은 잠시이고 영원한 것이 온다는 종말론적 관점을 갖도록 도우라"}
