    {"영어원문": "With all power and signs and lying wonders — there will be a show of miracles, but they will be lying wonders; the matter will be false, or the end evil.", "한국어번역": "모든 능력과 표적과 거짓 기사와 — 기적의 쇼가 있겠지만 그것들은 거짓 기사이다. 내용이 거짓이거나 목적이 악할 것이다.", "핵심통찰": "기적의 겉모습이 아닌 그 내용과 목적을 분별해야 한다"}
