    {"교리": "구원과 진리 사랑", "설명": "구원은 진리를 사랑하는 것과 연결된다. 단순한 지적 동의가 아닌 마음으로 진리를 받아들이고 사랑하는 것이 진정한 믿음이다. 진리를 사랑하는 자가 구원을 얻는다", "관련구절": "요 8:32, 요 14:6, 요일 3:18-19, 약 1:18"}
