    {"상황": "거짓 가르침에 끌리는 경향이 있는 분", "성경원리": "진리의 사랑이 없을 때 불의의 속임에 취약해진다. 진리를 사랑하는 것이 가장 강력한 방어이다. 진리를 매일 가까이 하는 것이 필요하다", "실제적용": "거짓 가르침의 매력이 어디에 있는지 함께 살피되 그 매력이 어떻게 속임인지를 성경으로 보여주라. 진리를 더 사랑하도록 말씀 생활을 강화하도록 도우라"}
