    {"상황": "진리를 알면서도 계속 죄를 선택하는 분", "성경원리": "진리를 계속 거부하면 결국 미혹에 빠질 위험이 있다. 진리를 알고도 거부하는 선택의 심각성을 인식해야 한다. 오늘 진리를 선택하는 결단이 필요하다", "실제적용": "진리를 알면서 거부하는 것의 심각성을 부드럽게 가르치되 정죄가 아닌 은혜로 접근하라. 성령의 도움을 구하며 진리를 사랑하는 마음을 회복하도록 함께 기도하라"}
