    {"상황": "자신의 불의에 대한 심판이 두려운 분", "성경원리": "심판은 진리를 믿지 않고 불의를 좋아하는 자들에게 임한다. 그리스도를 믿고 의를 사랑하는 자에게는 정죄함이 없다(롬 8:1). 믿음이 심판의 두려움을 이긴다", "실제적용": "두려움을 충분히 공감하되 그리스도 안에서의 구원 확신을 성경으로 확인하게 하라. 진리이신 그리스도를 믿는 것이 심판에서 자유로워지는 길임을 가르치라"}
