    {"원어": "ἁγιασμῷ πνεύματος (하기아스모 프뉴마토스)", "의미_문법": "성령의 거룩하게 하심 - 명사 남성 단수 여격+명사 중성 단수 속격. 성령이 거룩하게 하는 역사", "설교포인트": "성령이 거룩하게 하심이 구원의 도구이다. 구원은 성령의 역사이다. 성령이 우리를 그리스도를 위해 구별하고 거룩하게 만드신다"},
    {"원어": "πίστει ἀληθείας (피스테이 알레테이아스)", "의미_문법": "진리를 믿음으로 - 명사 여성 단수 여격+명사 여성 단수 속격. 진리에 대한 믿음", "설교포인트": "진리를 믿음이 구원의 수단이다. 성령의 역사와 인간의 믿음이 함께 작동한다. 하나님의 선택과 성령의 역사와 인간의 믿음이 모두 구원에 참여한다"}
