    {"항목": "감사의 재등장", "내용": "바울이 1:3과 2:13에서 두 번 감사를 언급한다. 두 번째 감사는 배도와 심판에 대한 어두운 묘사(3-12절) 이후에 온다. 이 대조가 더욱 선명하다. 멸망하는 자들과 달리 택하심을 받은 자들에 대한 감사이다", "목회적활용": "어두운 현실을 직시하면서도 하나님의 선택하심에 감사하는 것이 바른 신앙이다. 어둠이 짙을수록 빛이 더 빛난다"}
