    {"구분": "이사야의 부르심과 복음으로 부르심", "내용": "이사야가 땅 끝까지 구원을 선포했을 때(사 45:22) 이것이 복음을 통한 부르심의 예표이다. 복음이 온 세상에 선포되어 모든 민족을 부른다", "그리스도연결": "그리스도는 이사야가 예언한 구원자이시다(사 53장). 그분의 복음이 온 세상에 선포될 때 모든 민족이 부름을 받는다"}
