    {"영어원문": "To the obtaining of the glory of our Lord Jesus Christ — this is the high end and design of calling; the saints are called to reign in glory with Christ.", "한국어번역": "우리 주 예수 그리스도의 영광을 얻게 하려 하심이니라 — 이것이 부르심의 높은 목적이다. 성도들은 그리스도와 함께 영광 중에 통치하도록 부름받았다.", "핵심통찰": "부르심의 목적지가 영광이다. 이 소망이 현재의 모든 어려움을 이기게 한다"}
