    {"대지": "서론", "내용": "바울의 기도가 끝난다. 위로하시고 굳게 하시기를 원한다. 마음의 위로와 삶의 굳건함, 이 두 가지가 성도에게 가장 필요한 것이다. 하나님이 이 두 가지를 모두 주신다", "예화_적용": "의사가 환자에게 두 가지를 처방한다. 아픔을 위로하는 것과 앞으로 건강하게 사는 것. 하나님도 위로와 굳건함을 함께 주신다"},
    {"대지": "1대지: 마음을 위로하신다 (내면)", "내용": "파라칼레오, 옆에서 불러 위로하신다. 하나님이 성령을 통해 마음을 직접 위로하신다. 이 위로는 외부 환경이 아닌 마음 안에서 일어난다. 어떤 상황에서도 가능한 위로이다", "예화_적용": "어두운 방에 불을 켜면 방이 밝아지듯 하나님의 위로가 마음을 밝게 한다"},
    {"대지": "2대지: 선한 일과 말에 굳게 하신다 (외면)", "내용": "스테리조, 견고하게 세우신다. 모든 선한 일과 말에서 굳건하게 하신다. 행동과 말, 삶의 전 영역이다. 하나님이 성도의 삶 전체를 굳건하게 세우신다", "예화_적용": "건물의 기초가 든든하면 건물이 든든하듯 하나님이 삶의 기초를 굳건하게 하시면 삶 전체가 굳건해진다"},
    {"대지": "3대지: 위로가 먼저이고 굳건함이 그 다음이다 (순서)", "내용": "위로가 먼저이다. 마음이 위로를 받아야 선한 일과 말에서 굳건해질 수 있다. 이 순서가 중요하다. 위로 없이 굳건함을 요구하는 것은 무거운 짐을 지우는 것이다", "예화_적용": "기름을 넣어야 차가 달릴 수 있듯 위로를 받아야 선한 일을 감당할 수 있다"},
    {"대지": "결론", "내용": "하나님이 마음을 위로하시고 모든 선한 일과 말에 굳게 하신다. 이 두 가지 선물이 핍박받는 성도에게 필요한 것이다. 이 기도가 우리의 기도도 되게 하자. 오늘도 하나님의 위로를 받고 선한 삶을 살아가자", "예화_적용": "바울의 기도가 2,000년 후 오늘 우리에게도 필요하다. 우리 마음을 위로하시고 선한 일과 말에 굳게 하소서"}
